// atlas -> n8n (ADR-040). The body is one fixed shape; see docs/GUIDE.md, "n8n".
const b = $json.body || {};
const icon = { warning: '🔴', notice: '🟠', info: '🟢' }[b.severity] || '🔵';
const lines = [`${icon} ${b.title || 'atlas'}`];
if (b.kind === 'summary.daily' && b.summary) {
  for (const [k, v] of Object.entries(b.summary)) lines.push(`• ${k.replace(/_/g, ' ')}: ${v}`);
}
for (const e of (b.evidence || []).slice(0, 10)) lines.push(`– ${e}`);
if (b.opened_at) lines.push(`since ${b.opened_at}`);
return [{ json: { kind: b.kind, severity: b.severity, key: b.key, text: lines.join('\n') } }];
